/* botão de idioma */
function pill(){
  if(document.getElementById('lang'))return;
  var lay=document.documentElement.getAttribute('data-layout'),nav=document.getElementById('nav');if(!nav)return;
  var q=location.search.match(/[?&]v=(m|d)\b/),v=q?'v='+q[1]:'';
  function href(f,l){var p=[];if(l==='pt')p.push('l=pt');if(v)p.push(v);return f+(p.length?'?'+p.join('&'):'')}
  var el=document.createElement('div');el.id='lang';el.className='lang';el.setAttribute('role','navigation');el.setAttribute('aria-label','Idioma · Language · Idioma');
  el.innerHTML='<svg class="gl" viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3c3 3 3 15 0 18M12 3c-3 3-3 15 0 18"/></svg>'+
   [['pt','index.html','PT','Português','pt-BR'],['en','en.html','EN','English','en'],['es','es.html','ES','Español','es']].map(function(x){
     return '<a href="'+href(x[1],x[0])+'" hreflang="'+x[4]+'" lang="'+x[4]+'" title="'+x[3]+'" data-l="'+x[0]+'"'+(x[0]===LANG?' aria-current="true"':'')+'>'+x[2]+'</a>'}).join('');
  el.addEventListener('click',function(e){var a=e.target.closest&&e.target.closest('a[data-l]');if(a){try{localStorage.setItem('mk-lang',a.getAttribute('data-l'))}catch(x){}}});
  if(lay==='desktop'){var b=document.getElementById('navcart');nav.insertBefore(el,b||null)}else nav.parentNode.insertBefore(el,nav.nextSibling);
}
